param([string]$Phase2Root='R:\BaoVer2\ThucNgiem\RQ3_Phase2',[string]$Phase3Root='R:\BaoVer2\ThucNgiem\RQ3_Phase3')
$ErrorActionPreference='Stop'
$f=Get-Content -Raw (Join-Path $Phase2Root 'registry\phase2_frozen_manifest_v1.json')|ConvertFrom-Json
$ids=@($f.decisions|Where-Object evaluation_status -eq 'INCLUDED'|ForEach-Object case_id)
$map=@{
 NONE_VALID=@('VERIFIED','NONE','NONE'); LOCAL_COMPILATION_FAILURE=@('REPAIR_REQUIRED','COMPILATION_ERROR','LOCAL_TEST_REPAIR'); LOCAL_RUNTIME_OR_JUNIT_FAILURE=@('REPAIR_REQUIRED','SETUP_OR_RUNTIME_ERROR','LOCAL_TEST_REPAIR'); PLAN_TEST_MISMATCH=@('REPAIR_REQUIRED','PLAN_TEST_MISMATCH','REGENERATE_TEST'); STRUCTURAL_TARGET_NOT_EXECUTED=@('REPAIR_REQUIRED','TARGET_NOT_REACHED','REGENERATE_TEST'); EXPECTED_OBSERVATION_OR_ASSERTION_MISMATCH=@('REPAIR_REQUIRED','ASSERTION_ERROR','LOCAL_TEST_REPAIR'); WEAK_ORACLE_RELEVANT_MUTANT_SURVIVES=@('REPAIR_REQUIRED','WEAK_ORACLE','LOCAL_TEST_REPAIR'); SHARED_INFRASTRUCTURE_FAILURE=@('REPAIR_REQUIRED','SHARED_INFRASTRUCTURE_ERROR','SHARED_INFRASTRUCTURE_REPAIR'); INSUFFICIENT_CONTEXT=@('ABSTAIN','INSUFFICIENT_EVIDENCE','REQUEST_TOOL_EVIDENCE')
}
function NormCause($x){$s=[string]$x;if($s -match 'COMPILATION'){'COMPILATION_ERROR'}elseif($s -match 'RUNTIME|SETUP'){'SETUP_OR_RUNTIME_ERROR'}elseif($s -match 'PLAN'){'PLAN_TEST_MISMATCH'}elseif($s -match 'TARGET'){'TARGET_NOT_REACHED'}elseif($s -match 'WEAK'){'WEAK_ORACLE'}elseif($s -match 'SHARED'){'SHARED_INFRASTRUCTURE_ERROR'}elseif($s -match 'ASSERTION'){'ASSERTION_ERROR'}elseif($s -match 'INSUFFICIENT'){'INSUFFICIENT_EVIDENCE'}elseif($s -match '^NONE$'){'NONE'}else{'UNMAPPED'}}
function NormRoute($x){$s=[string]$x;if($s -match 'REGENERATE'){'REGENERATE_TEST'}elseif($s -match 'SHARED'){'SHARED_INFRASTRUCTURE_REPAIR'}elseif($s -match 'REQUEST'){'REQUEST_TOOL_EVIDENCE'}elseif($s -match 'LOCAL'){'LOCAL_TEST_REPAIR'}elseif($s -match '^NONE$'){'NONE'}else{'UNMAPPED'}}
$rows=@();$dir=Join-Path $Phase3Root 'artifacts\llm_predictions_gemini_flash_v1'
foreach($id in $ids){$g=Get-Content -Raw (Join-Path $Phase2Root ('gold\private\'+$id+'.json'))|ConvertFrom-Json;$truth=$map[$g.intended_gold_category]
 $rows += [PSCustomObject]@{case_id=$id;verifier='B0_BASIC_TOOL_GATE';decision='ABSTAIN';cause='INSUFFICIENT_EVIDENCE';route='REQUEST_TOOL_EVIDENCE';gold_category=$g.intended_gold_category;gold_decision=$truth[0];gold_cause=$truth[1];gold_route=$truth[2]}
 $p=Get-Content -Raw (Join-Path $dir ($id+'.json'))|ConvertFrom-Json
 foreach($v in 'B1','B2'){$z=$p.$v;$rows += [PSCustomObject]@{case_id=$id;verifier=if($v -eq 'B1'){'B1_GENERAL_REVIEWER'}else{'B2_SPECIALIZED_MULTI_AGENT'};decision=([string]$z.decision).ToUpper();cause=(NormCause $z.cause);route=(NormRoute $z.route);gold_category=$g.intended_gold_category;gold_decision=$truth[0];gold_cause=$truth[1];gold_route=$truth[2]}}
}
$out=Join-Path $Phase3Root 'artifacts';$rows|Export-Csv (Join-Path $out 'predictions_frozen_v1.csv') -NoTypeInformation -Encoding utf8
$metrics=foreach($v in $rows|Group-Object verifier){$r=@($v.Group);$repair=@($r|Where-Object gold_decision -eq 'REPAIR_REQUIRED');$fa=@($repair|Where-Object decision -eq 'VERIFIED');[ordered]@{verifier=$v.Name;cases=$r.Count;decision_accuracy=[math]::Round((@($r|Where-Object {$_.decision -eq $_.gold_decision}).Count/$r.Count),4);false_acceptance_rate=if($repair.Count){[math]::Round($fa.Count/$repair.Count,4)}else{0};cause_accuracy=[math]::Round((@($r|Where-Object {$_.cause -eq $_.gold_cause}).Count/$r.Count),4);route_accuracy=[math]::Round((@($r|Where-Object {$_.route -eq $_.gold_route}).Count/$r.Count),4);abstention_rate=[math]::Round((@($r|Where-Object decision -eq 'ABSTAIN').Count/$r.Count),4);decision_coverage=[math]::Round((@($r|Where-Object decision -ne 'ABSTAIN').Count/$r.Count),4)}}
[ordered]@{phase2_manifest='FROZEN_REDUCED_EVALUATION_SET';evaluation_cases=$ids.Count;scoring_note='Private gold joined only in this scorer after predictions were final.';metrics=$metrics}|ConvertTo-Json -Depth 5|Set-Content (Join-Path $out 'metrics_frozen_v1.json') -Encoding utf8
$metrics|ConvertTo-Json -Depth 4
